    missing = [i for i in catalog if i not in seen]
    if missing:
        return {'ok': False, 'errors': ['missing:' + ','.join(missing)], 'tree': None,
                'size': None, 'coords': None, 'rows': []}
    if len(stack) != 1:
        return {'ok': False, 'errors': [f'leftover:{len(stack)}'], 'tree': None,
                'size': None, 'coords': None, 'rows': []}

    root, root_size = stack[0]
    coords = {}
